import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  FetchResult,
  TransformResult,
  LoadResult,
  PipelineConfig,
  PipelineResult,
} from './types';

export type { PipelineConfig, PipelineResult };

export function runPipeline(
  config: PipelineConfig,
  callback: (err: Error | null, result?: PipelineResult) => void
): void {
  // Nested callback hell
  fetchUrl(config.url, (fetchErr, fetchRes) => {
    if (fetchErr || !fetchRes) {
      callback(fetchErr ?? new Error('Fetch failed'));
      return;
    }

    transformData(fetchRes, (transErr, transRes) => {
      if (transErr || !transRes) {
        callback(transErr ?? new Error('Transform failed'));
        return;
      }

      loadRecord(config.tableName, transRes, (loadErr, loadRes) => {
        if (loadErr || !loadRes) {
          callback(loadErr ?? new Error('Load failed'));
          return;
        }

        callback(null, {
          fetch: fetchRes,
          transform: transRes,
          load: loadRes,
        });
      });
    });
  });
}

