export async function fetch(
  url: string,
  callback?: (err: Error | null, result?: FetchResult) => void
): Promise<FetchResult> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        if (!url.startsWith('http://') && !url.startsWith('https://')) {
          throw new Error(`Invalid URL: ${url}`));
