  get fieldName(): string {
    return this.field;
  }
}

export class LoadError extends Error {
  readonly table: string;
  readonly operation: string;

  constructor(message: string, table: string, operation: string = 'insert') {
    super(message);
    this.name = 'LoadError';
    this.table = table;
    this.operation = operation;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get tableName(): string {
    return this.table;
  }
}

import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  PipelineStageError,
  FetchResult,
  TransformResult,
  LoadResult,
  FetchError,
  TransformError,
  LoadError,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError, PipelineStageError };

export async function runPipeline(
  config: PipelineConfig
): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    if (err instanceof FetchError) {
      throw new PipelineStageError(
        `Fetch stage failed for URL "${err.url}" (status ${err.status}): ${err.message}`,
        'fetch',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    if (err instanceof TransformError) {
      throw new PipelineStageError(
        `Transform stage failed for field "${err.field}" (expected ${err.expectedType}): ${err.message}`,
        'transform',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    if (err instanceof LoadError) {
      throw new PipelineStageError(
        `Load stage failed for table "${err.table}" during operation "${err.operation}": ${err.message}`,
        'load',
        err
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineStageError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}

export const pipeline = runPipeline;

