import { describe, it, expect } from 'vitest';
import { runPipeline } from './pipeline';
import { PipelineError, PipelineStageError } from './types';

describe('pipeline', () => {
  it('successfully executes the full pipeline end-to-end', async () => {
    const result = await runPipeline({
      url: 'https://api.example.com/items',
      tableName: 'items_table',
    });

    expect(result).toBeDefined();
    expect(result.fetch.status).toBe(200);
    expect(result.fetch.url).toBe('https://api.example.com/items');

    expect(result.transform.slug).toBe('sample-payload');
    expect(result.transform.sourceUrl).toBe('https://api.example.com/items');
    expect(result.transform.id).toBe(1);

    expect(result.load.success).toBe(true);
    expect(result.load.insertedId).toBe(1);
    expect(result.load.table).toBe('items_table');
  });

  it('wraps fetch errors in PipelineStageError with stage="fetch"', async () => {
    try {
      await runPipeline({
        url: 'invalid-url',
        tableName: 'items_table',
      });
      expect.unreachable('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const stageErr = err as PipelineStageError;
      expect(stageErr.stage).toBe('fetch');
      expect(stageErr.message).toContain('Fetch stage failed');
      expect(stageErr.cause).toBeDefined();
    }
  });

  it('wraps load errors in PipelineStageError with stage="load"', async () => {
    try {
      await runPipeline({
        url: 'https://api.example.com/items',
        tableName: '',
      });
      expect.unreachable('Should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(PipelineError);
      expect(err).toBeInstanceOf(PipelineStageError);
      const stageErr = err as PipelineStageError;
      expect(stageErr.stage).toBe('load');
      expect(stageErr.message).toContain('Load stage failed');
      expect(stageErr.cause).toBeDefined();
    }
  });
});

